package com.arqly.backend.service;
import com.arqly.backend.dto.FinancialDtos.*;import com.arqly.backend.entity.*;import com.arqly.backend.exception.NotFoundException;import com.arqly.backend.repository.*;import java.math.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class FinancialQueryService { private final FinancialEntryRepository entries;private final FinancialInstallmentRepository installments;private final ProjectRepository projects;private final ClientRepository clients;public FinancialQueryService(FinancialEntryRepository e,FinancialInstallmentRepository i,ProjectRepository p,ClientRepository c){entries=e;installments=i;projects=p;clients=c;}@Transactional(readOnly=true) public ProjectFinancialSummary project(UUID tenant,UUID id){projects.findByIdAndTenantIdAndDeletedFalse(id,tenant).orElseThrow(()->new NotFoundException("Projeto não encontrado."));return summary(filter(tenant,e->e.getProject()!=null&&e.getProject().getId().equals(id)));}@Transactional(readOnly=true) public ClientFinancialSummary client(UUID tenant,UUID id){clients.findByIdAndTenantIdAndDeletedFalse(id,tenant).orElseThrow(()->new NotFoundException("Cliente não encontrado."));var list=filter(tenant,e->e.getClient()!=null&&e.getClient().getId().equals(id)&&e.getType()==FinancialEntryType.RECEIVABLE);BigDecimal expected=total(list,false),actual=total(list,true),overdue=list.stream().flatMap(e->installments.findAllByEntryIdOrderByInstallmentNumber(e.getId()).stream()).filter(i->i.getStatus()!=FinancialInstallmentStatus.PAID&&i.getStatus()!=FinancialInstallmentStatus.CANCELLED&&i.getDueDate().isBefore(LocalDate.now())).map(i->i.getAmount().subtract(i.getSettledAmount())).reduce(BigDecimal.ZERO,BigDecimal::add);return new ClientFinancialSummary(expected,actual,expected.subtract(actual),overdue);}@Transactional(readOnly=true) public ProjectFinancialSummary summary(List<FinancialEntry> l){BigDecimal ei=total(type(l,FinancialEntryType.RECEIVABLE),false),ai=total(type(l,FinancialEntryType.RECEIVABLE),true),ee=total(type(l,FinancialEntryType.PAYABLE),false),ae=total(type(l,FinancialEntryType.PAYABLE),true);return new ProjectFinancialSummary(ei,ai,ee,ae,ei.subtract(ee),ai.subtract(ae));}private List<FinancialEntry> filter(UUID tenant,java.util.function.Predicate<FinancialEntry> p){return entries.findAllByTenantIdAndDeletedFalseOrderByCreatedAtDesc(tenant).stream().filter(e->e.getStatus()!=FinancialEntryStatus.CANCELLED).filter(p).toList();}private List<FinancialEntry> type(List<FinancialEntry> l,FinancialEntryType t){return l.stream().filter(e->e.getType()==t).toList();}private BigDecimal total(List<FinancialEntry> l,boolean actual){return l.stream().flatMap(e->installments.findAllByEntryIdOrderByInstallmentNumber(e.getId()).stream()).map(i->actual?i.getSettledAmount():i.getAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);} }
